const rawContent = items[0].json.data;
const maxTokens = 70000; // GPT-3.5 için güvenli limit
const avgCharsPerToken = 4; // Yaklaşık oran
const maxChars = maxTokens * avgCharsPerToken;

// İçeriği temizle ve önemli kısımları çıkar
function extractImportantContent(content) {
  let cleanContent = content;

  // HTML ise sadece text içeriğini al
  if (content.includes('<html') || content.includes('<!DOCTYPE')) {
    // Script ve style tag'lerini kaldır
    cleanContent = content
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ') // HTML tag'lerini kaldır
      .replace(/\s+/g, ' ') // Çoklu boşlukları tek boşluk yap
      .trim();
  }

  // API endpoint pattern'lerini bul ve öne çıkar
  const endpointPatterns = [
    // HTTP method + path patterns
    /(GET|POST|PUT|PATCH|DELETE)\s+\/[^\s<>"\n\r]+/gi,
    /(GET|POST|PUT|PATCH|DELETE):\s*\/[^\s<>"\n\r]+/gi,
    // URL patterns
    /https?:\/\/[^\s<>"\n\r]+\/(api|v\d+)\/[^\s<>"\n\r]+/gi,
    // API doc sections
    /endpoint[s]?[:\s][^\n\r]{0,200}/gi,
    /authentication[:\s][^\n\r]{0,200}/gi,
    /base[\s_-]?url[:\s][^\n\r]{0,200}/gi
  ];

  let extractedParts = [];

  // Endpoint'leri bul ve çıkar
  for (const pattern of endpointPatterns) {
    const matches = cleanContent.match(pattern) || [];
    extractedParts.push(...matches);
  }

  // OpenAPI/Swagger JSON kontrolü
  if (content.includes('"openapi"') || content.includes('"swagger"')) {
    try {
      const jsonMatch = content.match(/{[\s\S]*}/); // En büyük JSON bloğu
      if (jsonMatch) {
        const jsonStr = jsonMatch[0];
        const jsonObj = JSON.parse(jsonStr);

        // Sadece önemli kısımları al
        const importantJson = {
          openapi: jsonObj.openapi || jsonObj.swagger,
          info: jsonObj.info,
          servers: jsonObj.servers,
          paths: {},
          components: {
            securitySchemes: jsonObj.components?.securitySchemes
          }
        };

        // Path'leri sınırlı şekilde ekle
        const paths = jsonObj.paths || {};
        let pathCount = 0;
        for (const [path, methods] of Object.entries(paths)) {
          if (pathCount >= 50) break; // Maksimum 50 endpoint
          importantJson.paths[path] = methods;
          pathCount++;
        }

        return JSON.stringify(importantJson, null, 2);
      }
    } catch (e) {
      // JSON parse hatası, normal flow devam eder
    }
  }

  // İçeriği parçalara böl ve önemli kısımları birleştir
  const sections = [
    extractedParts.join('\n'),

    // API ile ilgili bölümleri ara
    ...cleanContent.split(/\n|\.|\;/).filter(line => {
      const lowerLine = line.toLowerCase();
      return (lowerLine.includes('api') || 
              lowerLine.includes('endpoint') ||
              lowerLine.includes('authentication') ||
              lowerLine.includes('product') ||
              lowerLine.includes('category') ||
              lowerLine.includes('order') ||
              lowerLine.includes('item') ||
              lowerLine.includes('menu')) &&
             line.length > 10 && line.length < 500;
    }).slice(0, 100) // İlk 100 relevantline
  ];

  let result = sections.join('\n').substring(0, maxChars);

  return result;
}

const processedContent = extractImportantContent(rawContent);

return [{
  json: {
    data: processedContent,
    originalLength: rawContent.length,
    processedLength: processedContent.length,
    truncated: rawContent.length > maxChars
  }
}];

