const aiResponse = items[0].json.message.content;
const platformName = $node["Webhook Trigger"].json.body.platformName;

try {
  // AI response'u JSON olarak parse et
  const analysisResult = JSON.parse(aiResponse);

  // Endpoint'leri kategorilere ayır
  const categoryEndpoints = (analysisResult.endpoints || []).filter(e => 
    e.category === 'category' || 
    e.path.toLowerCase().includes('category') ||
    e.path.toLowerCase().includes('menu') ||
    e.path.toLowerCase().includes('section')
  );

  const productEndpoints = (analysisResult.endpoints || []).filter(e => 
    e.category === 'product' || 
    e.path.toLowerCase().includes('product') ||
    e.path.toLowerCase().includes('item') ||
    e.path.toLowerCase().includes('dish')
  );

  const orderEndpoints = (analysisResult.endpoints || []).filter(e => 
    e.category === 'order' || 
    e.path.toLowerCase().includes('order') ||
    e.path.toLowerCase().includes('check') ||
    e.path.toLowerCase().includes('purchase')
  );

  return [{
    json: {
      platformName,
      categoryEndpoints,
      productEndpoints,
      orderEndpoints,
      authentication: analysisResult.authentication || {},
      baseUrl: analysisResult.baseUrl || '',
      dataStructures: analysisResult.dataStructures || {},
      rateLimit: analysisResult.rateLimit || {},
      aiAnalysis: true,
      analysisTimestamp: new Date().toISOString()
    }
  }];

} catch (error) {
  // AI response parse edilemezse fallback regex kullan
  console.log('AI parse failed, using fallback regex');

  const docContent = $node["Process & Truncate Content"].json.data;
  const endpoints = [];

  // Fallback regex parsing
  const endpointPatterns = [
    /(GET|POST|PUT|PATCH|DELETE)\s+(\/[^\s<>\"\n\r]+)/gi,
    /(GET|POST|PUT|PATCH|DELETE):\s*(\/[^\s<>\"\n\r]+)/gi
  ];

  for (const pattern of endpointPatterns) {
    let match;
    while ((match = pattern.exec(docContent)) !== null) {
      if (match[1] && match[2]) {
        endpoints.push({
          method: match[1].toUpperCase(),
          path: match[2],
          category: 'other',
          source: 'fallback'
        });
      }
    }
  }

  return [{
    json: {
      platformName,
      categoryEndpoints: endpoints.filter(e => e.path.toLowerCase().includes('category')),
      productEndpoints: endpoints.filter(e => e.path.toLowerCase().includes('product')),
      orderEndpoints: endpoints.filter(e => e.path.toLowerCase().includes('order')),
      authentication: {},
      baseUrl: '',
      dataStructures: {},
      aiAnalysis: false,
      fallbackUsed: true,
      error: error.message
    }
  }];
}

const analysisData = items[0].json;

// Her entity type için ayrı ayrı data mapping workflow'unu tetikle
const entityTypes = [];

if (analysisData.productEndpoints && analysisData.productEndpoints.length > 0) {
  entityTypes.push({
    entityType: 'product',
    endpoints: analysisData.productEndpoints,
    sampleEndpoint: analysisData.productEndpoints.find(e => e.method === 'GET')?.path || analysisData.productEndpoints[0]?.path
  });
}

if (analysisData.categoryEndpoints && analysisData.categoryEndpoints.length > 0) {
  entityTypes.push({
    entityType: 'category',
    endpoints: analysisData.categoryEndpoints,
    sampleEndpoint: analysisData.categoryEndpoints.find(e => e.method === 'GET')?.path || analysisData.categoryEndpoints[0]?.path
  });
}

if (analysisData.orderEndpoints && analysisData.orderEndpoints.length > 0) {
  entityTypes.push({
    entityType: 'order',
    endpoints: analysisData.orderEndpoints,
    sampleEndpoint: analysisData.orderEndpoints.find(e => e.method === 'GET')?.path || analysisData.orderEndpoints[0]?.path
  });
}

return entityTypes.map(entity => ({
  json: {
    ...analysisData,
    currentEntityType: entity.entityType,
    currentEndpoints: entity.endpoints,
    currentSampleEndpoint: entity.sampleEndpoint
  }
}));
